@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix sosa: <http://www.w3.org/ns/sosa/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <http://example.org/my-feature/c1> ;
            sh:resultMessage "Collection members must match sosa:observedProperty if present" ;
            sh:resultPath sosa:observedProperty ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ sh:message "Collection members must match sosa:observedProperty if present" ;
                    sh:select """
            PREFIX sh: <http://www.w3.org/ns/shacl#>
            PREFIX sosa: <http://www.w3.org/ns/sosa/>
            PREFIX geojson: <https://purl.org/geojson/vocab#>
            SELECT $this (sosa:observedProperty as ?path) (GROUP_CONCAT(?prop; separator=';') AS ?value)
             WHERE {
                OPTIONAL { $this sosa:observedProperty ?prop }
                OPTIONAL { $this (sosa:hasMember|geojson:features)+ ?obs .
                    ?obs  sosa:observedProperty ?prop }
            }
            GROUP BY ?prop
            HAVING (count(?prop) < 1)
        """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape <https://www.ogc.org/rules/sosa/#testObservedPropertyConsistent> ;
            sh:value "" ],
        [ a sh:ValidationResult ;
            sh:focusNode <http://example.org/my-feature/a1> ;
            sh:resultMessage "sosa:observedProperty is required" ;
            sh:resultPath sosa:observedProperty ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ sh:message "sosa:observedProperty is required" ;
                    sh:select """
            PREFIX sh: <http://www.w3.org/ns/shacl#>
            PREFIX sosa: <http://www.w3.org/ns/sosa/>
            PREFIX geojson: <https://purl.org/geojson/vocab#>
            SELECT $this (sosa:observedProperty as ?path) (GROUP_CONCAT(?prop; separator=';') AS ?value)
            WHERE {
                OPTIONAL { $this sosa:observedProperty ?prop .
                 $this (sosa:hasResult|sosa:hasSimpleResult) ?result_so_observation }
                OPTIONAL { ?collection (sosa:hasMember|geojson:features)+ $this ; sosa:observedProperty ?prop }
            }
            GROUP BY ?prop
            HAVING (count(?prop) < 1)
        """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape <https://www.ogc.org/rules/sosa/#testObservedPropertyPresent> ;
            sh:value "" ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix sosa: <http://www.w3.org/ns/sosa/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <http://example.org/my-feature/c1> ;
            sh:resultMessage "Collection member values do not match those of the collections (http://www.w3.org/ns/sosa/observedProperty property in http://example.org/my-feature/a2: http://example.org/my-feature/p3 != http://example.org/my-feature/p1)" ;
            sh:resultPath sosa:observedProperty ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ sh:select """
        PREFIX sosa: <http://www.w3.org/ns/sosa/>
        PREFIX geojson: <https://purl.org/geojson/vocab#>
        PREFIX time: <http://www.w3.org/2006/time#>
        SELECT $this ?path (?member AS ?value) ?failedValue WHERE {
            $this (sosa:hasMember|^sosa:memberOf)+ ?member ;
                ?path ?collectionValue .
            ?member ?path ?memberValue .
            FILTER(?path in ( sosa:resultTime, sosa:phenomenonTime, sosa:hasResult, sosa:hasSimpleResult,
                sosa:hasFeatureOfInterest, sosa:hasUltimateFeatureOfInterest, sosa:observedProperty, sosa:madeBySystem,
                sosa:usedProcedure, sosa:madeBySensor, sosa:madeBySampler, sosa:isSampleOf, sosa:madeByActuator,
                sosa:actsOn, sosa:actsOnProperty, sosa:hasInputValue, sosa:observationRelatedTo,
                sosa:relatedObservation, sosa:resultQuality, sosa:isOriginalSampleOf, sosa:isResultOfMadeBySampler,
                sosa:isResultOfUsedProcedure ))
            FILTER((isLiteral(?collectionValue) || isIRI(?collectionValue)) && ?collectionValue != ?memberValue)
            FILTER NOT EXISTS { $this ?path ?memberValue }
            FILTER NOT EXISTS { ?collectionValue a time:Interval }
            BIND(CONCAT(STR(?memberValue), " != ", STR(?collectionValue)) as ?failedValue)
        }
    """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape <https://www.ogc.org/rules/sosa/#testCollectionPropertyValues> ;
            sh:value <http://example.org/my-feature/a2> ] .

